- [Major] Local Git sources/remotes bypass workspace scope — clone scopes only the destination, then passes `operation.source` directly to Git after URL-shape checks; `set-remote` similarly allows local paths. A web client with a narrow `--workspace-root` can use `/home/user/private-repo`, `../private-repo`, or `file:///...` as a clone source/remote and bring out-of-scope repository contents into the managed workspace. Evidence `cli/src/host/repositoryManager.ts:221`, `cli/src/host/repositoryManager.ts:231`.
  Suggested fix:
  ```ts
  import { fileURLToPath } from 'node:url'
  import { isAbsolute, resolve } from 'node:path'

  function isLocalGitSource(source: string): boolean {
      return source.startsWith('file://')
          || source.startsWith('.')
          || source.startsWith('/')
          || /^[A-Za-z]:[\\/]/.test(source)
  }

  private async resolveGitSource(source: string, cwd: string): Promise<string> {
      assertSafeRemoteUrl(source)
      if (source.startsWith('file://')) {
          return await this.scope.resolveReadable(fileURLToPath(source))
      }
      if (isLocalGitSource(source)) {
          return await this.scope.resolveReadable(isAbsolute(source) ? source : resolve(cwd, source))
      }
      return gitFallbackSource(source)
  }
  ```
